//This service should NOT create any data on disk, just provide input data as JSON so it's safe to be called multiple times.
//Parameters are declared for each test, and sometimes later tests use as value parameters that have been declared for earlier tests; considering this, whenever removing input parameters, make sure they are not used in other tests

//variable to guarantee unicity of entities created throughout these tests
let shortDate = dateFormat(new Date(), "ddhhmmssSSS");
let str_HTTP = "http://";
let str_HTTPS = "https://";
let str_Domain = "localhost";
let str_Port = 3001;
let str_BaseURL = str_Domain+":"+str_Port+"/contentloadertest/";

//The result of this service is a JSON representing the input params required for the ExecuteTest services
let result = new Object();
result.tests = new Array();

//test 1
let test1 = {
    TestName: "1. Unauthenticated Get",
    ServiceName: "UnauthGet",
    InputParams: {
        URLEndpoint: str_HTTP+str_BaseURL+"TestGetServiceUnauth"
    },
    ExpectedOutput: {
        Response: "{\"MySampleKey\":\"MySampleValue\"}"
    }
};
result.tests.push(test1);

//test 2
let test2 = {
    TestName: "2. Unauthenticated POST",
    ServiceName: "UnauthPost",
    InputParams: {
        URLEndpoint: str_HTTP + str_BaseURL + "TestPostServiceUnauth"
