var html = "<HTML><style>table {    border-collapse: collapse;}th, td {    border: 1px solid #ccc;    padding: 4px 8px;}th {    background-color: #f2f2f2;}</style><HEAD><TITLE>Execution Of RunAllTests</TITLE><META http-equiv='Content-Type' content='text/html'></META><META http-equiv='cache-control' content='no-cache, no-store'></META><META http-equiv='expires' content='-1'></META><META http-equiv='pragma' content='no-cache, no-store'></META></HEAD><BODY><BR/><H1>RunAllTests</H1>";
html += "<TABLE><TR><TH>Test Name</TH><TH>Expected</TH><TH>Inputs</TH><TH>Start Time</TH><TH>End Time</TH><TH>Passed</TH><TH>Comments</TH></TR>";

tests.rows.toArray().forEach(row => {
	{
		html += "<TR>";
		html += "<TD>" + row.testName + "</TD>";
		html += "<TD>" + row.expectedOutput + "</TD>";
		html += "<TD>" + row.inputParams + "</TD>";
		html += "<TD>" + row.startTimestamp + "</TD>";
		html += "<TD>" + row.endTimestamp + "</TD>";
		html += "<TD>" + row.passed + "</TD>";
		html += "<TD>" + ((row.comments == null) ? "" : row.comments) + "</TD>";
		html += "</TR>";
	}
});

html += "</TABLE></BODY></HTML>";

var result = html;

//1. Initializing the test data. Optional.
let testData = me.CreateTestData();

//2. Create a variable that will store all the results 
var prevTestResult= Resources["InfoTableFunctions"].CreateInfoTableFromDataShape({
    infoTableName : "InfoTable",
    dataShapeName : "ContentLoaderExtended.TestResultData_DS"
});

//3. The CreateTestData contains service Names for each test; we will iterate through those

for (var i = 0; i < testData.tests.length; i++) {  

   // logger.warn("Starting to execute Test: "+testData.tests[i].ServiceName +"; Test index: "+i);
    pause(10);
    prevTestResult=me[testData.tests[i].ServiceName]({PreviousTestResults:prevTestResult,
                                TestName: testData.tests[i].TestName /* STRING */,
								InputParams: testData.tests[i].InputParams /* JSON */,
								ExpectedOutput: testData.tests[i].ExpectedOutput  /* JSON */}); 
    pause(10);
}
//4. delete test data
pause(50);
me.DeleteTestData({InputParams:testData});
result = prevTestResult;

let result =  me.RunAllTests();
result =  me.FormatTestResults({
	tests: result /* INFOTABLE */
});

