pause(1);
let testResult;
let str_Comments;
//Input data is defined in the CreateTestData Service
try {
	let url = InputParams.URLEndpoint;
	//it record
	let expectedResponseCode = ExpectedOutput.ResponseCode;
	// result: JSON
	let result = Resources["ContentLoaderExtended"].ExecuteHttpRequest({
		proxyScheme: undefined /* STRING {"defaultValue":"http"} */ ,
		headers: undefined /* JSON */ ,
		ignoreSSLErrors: undefined /* BOOLEAN */ ,
		method: "DELETE" /* STRING */ ,
		useNTLM: undefined /* BOOLEAN {"defaultValue":false} */ ,
		keyStorePassword: undefined /* STRING */ ,
		withResponseStatus: true /* BOOLEAN {"defaultValue":false} */ ,
		workstation: undefined /* STRING {"defaultValue":""} */ ,
		useProxy: undefined /* BOOLEAN {"defaultValue":false} */ ,
		withCookies: undefined /* BOOLEAN {"defaultValue":false} */ ,
		proxyHost: undefined /* STRING {"defaultValue":""} */ ,
		url: url /* STRING */ ,
		content: undefined /* STRING */ ,
		timeout: undefined /* NUMBER {"defaultValue":60} */ ,
		keepAlivePool: undefined /* STRING */ ,
		proxyPort: undefined /* INTEGER {"defaultValue":8080} */ ,
		trustStorePassword: undefined /* STRING */ ,
		password: undefined /* STRING */ ,
		withResponseHeaders: undefined /* BOOLEAN {"defaultValue":false} */ ,
		domain: undefined /* STRING {"defaultValue":""} */ ,
		trustStorePath: undefined /* STRING */ ,
		contentType: undefined /* STRING */ ,
		keyStorePath: undefined /* STRING */ ,
		username: undefined /* STRING */
	});
	testResult = result.responseStatus.statusCode == expectedResponseCode;
    if (!testResult) str_Comments = "Received response code: "+result.responseStatus.statusCode;
} catch (err) {
	testResult = false;
	str_Comments = "Error: " + err.message + "; Stack: " + err.stack;
}

